CREATE SCHEMA IF NOT EXISTS crm;
CREATE SEQUENCE crm.ticket_public_id_seq START 100000;
CREATE TABLE crm.customer_profiles(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),customer_id uuid NOT NULL REFERENCES identity.users(id) ON DELETE CASCADE,tier text NOT NULL DEFAULT 'standard' CHECK(tier IN('standard','verified','business','vip','restricted')),health_score smallint NOT NULL DEFAULT 100 CHECK(health_score BETWEEN 0 AND 100),owner_id uuid,first_seen_at timestamptz NOT NULL DEFAULT clock_timestamp(),last_contact_at timestamptz,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,customer_id));
CREATE TABLE crm.tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),public_id bigint NOT NULL DEFAULT nextval('crm.ticket_public_id_seq'),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),customer_id uuid NOT NULL REFERENCES identity.users(id),channel text NOT NULL CHECK(channel IN('web','chat','phone','email','staff')),priority text NOT NULL CHECK(priority IN('urgent','high','normal','low')),state text NOT NULL DEFAULT 'open' CHECK(state IN('open','assigned','waiting_customer','waiting_internal','resolved','closed')),subject varchar(160) NOT NULL,fingerprint char(64) NOT NULL,assignee_id uuid,assigned_at timestamptz,assignment_expires_at timestamptz,sla_due_at timestamptz NOT NULL,sla_breached_at timestamptz,resolved_at timestamptz,closed_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,public_id));
CREATE INDEX crm_ticket_queue_idx ON crm.tickets(tenant_id,state,sla_due_at,priority);CREATE INDEX crm_ticket_customer_idx ON crm.tickets(tenant_id,customer_id,created_at DESC);CREATE INDEX crm_ticket_fingerprint_idx ON crm.tickets(tenant_id,fingerprint,created_at DESC);
CREATE TABLE crm.interactions(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES platform.tenants(id),ticket_id uuid REFERENCES crm.tickets(id) ON DELETE CASCADE,customer_id uuid REFERENCES identity.users(id),actor_id uuid,kind text NOT NULL CHECK(kind IN('message','call','email','note','status','assignment','system')),channel text NOT NULL CHECK(channel IN('web','chat','phone','email','staff','system')),body text NOT NULL CHECK(octet_length(body)<=32000),is_internal boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX crm_interaction_timeline_idx ON crm.interactions(tenant_id,customer_id,created_at DESC,id DESC);CREATE INDEX crm_interaction_ticket_idx ON crm.interactions(tenant_id,ticket_id,created_at,id);
CREATE TABLE crm.tags(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),key varchar(60) NOT NULL,label varchar(80) NOT NULL,color char(7) NOT NULL DEFAULT '#64748b',created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,key));
CREATE TABLE crm.customer_tags(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),customer_id uuid NOT NULL REFERENCES identity.users(id) ON DELETE CASCADE,tag_id uuid NOT NULL REFERENCES crm.tags(id) ON DELETE CASCADE,actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,customer_id,tag_id));
CREATE TABLE crm.tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),customer_id uuid NOT NULL REFERENCES identity.users(id) ON DELETE CASCADE,ticket_id uuid REFERENCES crm.tickets(id) ON DELETE SET NULL,assignee_id uuid NOT NULL,title varchar(160) NOT NULL,state text NOT NULL DEFAULT 'open' CHECK(state IN('open','doing','done','cancelled')),due_at timestamptz,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp());CREATE INDEX crm_task_queue_idx ON crm.tasks(tenant_id,assignee_id,state,due_at) WHERE state IN('open','doing');
CREATE TABLE crm.macros(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),key varchar(60) NOT NULL,title varchar(120) NOT NULL,body text NOT NULL,channel text NOT NULL DEFAULT 'any' CHECK(channel IN('any','web','chat','phone','email')),active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,key,version));
CREATE TABLE crm.satisfaction(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),ticket_id uuid NOT NULL REFERENCES crm.tickets(id) ON DELETE CASCADE,customer_id uuid NOT NULL REFERENCES identity.users(id),score smallint NOT NULL CHECK(score BETWEEN 1 AND 5),comment varchar(1000) NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,ticket_id));
INSERT INTO crm.customer_profiles(tenant_id,customer_id)SELECT tenant_id,id FROM identity.users ON CONFLICT DO NOTHING;
DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['customer_profiles','tickets','interactions','tags','customer_tags','tasks','macros','satisfaction'] LOOP EXECUTE format('ALTER TABLE crm.%I ENABLE ROW LEVEL SECURITY',table_name);EXECUTE format('ALTER TABLE crm.%I FORCE ROW LEVEL SECURITY',table_name);EXECUTE format('CREATE POLICY %I ON crm.%I USING(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid)',table_name||'_tenant_isolation',table_name);END LOOP;END $$;
